"""House Robber — rob this house plus the best up to i-2, or skip it.

Time: O(n)   Space: O(1)
"""
from typing import List


class Solution:
    def rob(self, nums: List[int]) -> int:
        skip = take = 0
        for value in nums:
            skip, take = max(skip, take), skip + value
        return max(skip, take)
